class Solution {
    public int maxProfit(int[] prices) {
        int best = 0;
        int days = prices.length;
        for (int buy1 = 0; buy1 < days; buy1++) {
            for (int sell1 = buy1 + 1; sell1 < days; sell1++) {
                best = Math.max(best, prices[sell1] - prices[buy1]);
                for (int buy2 = sell1 + 1; buy2 < days; buy2++) {
                    for (int sell2 = buy2 + 1; sell2 < days; sell2++) {
                        int profit = prices[sell1] - prices[buy1]
                                + prices[sell2] - prices[buy2];
                        best = Math.max(best, profit);
                    }
                }
            }
        }
        return best;
    }
}

